//
// Sound for gb2swf games under Ruffle. Ruffle does not support SampleDataEvent
// (sound generated by the SWF itself), so the SWF sends its samples here through
// ExternalInterface every frame and this script plays them back to back with
// WebAudio. In the real Flash Player this file is not used.
(function () {
  "use strict";
  const RATE = 44100;
  let ctx = null, gain = null, next = 0, volume = 1;

  function ensure() {
    if (!ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ctx = new AC();
      gain = ctx.createGain();
      gain.gain.value = volume;
      gain.connect(ctx.destination);
      // Browsers only allow sound after a click or key press
      const resume = () => ctx.state === "suspended" && ctx.resume();
      addEventListener("pointerdown", resume, true);
      addEventListener("keydown", resume, true);
    }
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  }

  // Called by the SWF to find out whether this route exists
  window.gb2swfAudioReady = function () { return ensure() != null; };

  // samples: interleaved L,R (floats -1..1) at 44.1 kHz
  window.gb2swfAudio = function (samples) {
    const c = ensure();
    if (!c || c.state !== "running" || !samples || samples.length < 2) return;
    const n = samples.length >> 1;
    const buf = c.createBuffer(2, n, RATE);
    const L = buf.getChannelData(0), R = buf.getChannelData(1);
    for (let i = 0, j = 0; i < n; i++, j += 2) { L[i] = samples[j]; R[i] = samples[j + 1]; }
    const src = c.createBufferSource();
    src.buffer = buf;
    src.connect(gain);
    const now = c.currentTime;
    // Too far ahead: drop this piece; fallen behind: start again with a little margin
    if (next > now + 0.25) return;
    if (next < now + 0.01) next = now + 0.05;
    src.start(next);
    next += n / RATE;
  };

  window.gb2swfAudioVolume = function (v) { volume = v; if (gain) gain.gain.value = v; };
  // Clears the queue (e.g. when a page switches games)
  window.gb2swfAudioReset = function () { next = 0; };
})();
